rcSource.top = 0; rcSource.left = 0; 
rcSource.bottom = 100; rcSource.right = 200; 
rcDest.top = 0; rcDest.left = 201; 
rcDest.bottom = 100; rcDest.right = 401; 
HRESULT hr = lpDDS->Blt(&rcDest, 
 lpDDS, 
 &rcSource, 
 DDBLT_WAIT | DDBLT_DDFX, 
